const normalize = value =>
  String(value ?? "").trim().toLowerCase();

const normalizeText = value =>
  String(value ?? "").trim();

const emailPattern =
  /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

return $input.all().map((item, index) => {
  const customer = item.json;

  const business = normalize(customer.business_name);
  const email = normalize(customer.email);
  const name = normalizeText(customer.customer_name);
  const service = normalizeText(customer.service_requested);

  const budget = Number(customer.budget);

  if (
    !business ||
    !name ||
    !service ||
    !emailPattern.test(email) ||
    customer.budget === "" ||
    customer.budget === null ||
    customer.budget === undefined ||
    !Number.isFinite(budget) ||
    budget < 0
  ) {
    throw new Error(
      `Invalid customer record at item ${index + 1}`
    );
  }

  return {
    json: {
      ...customer,
      business_name: business,
      customer_name: name,
      email,
      phone: normalizeText(customer.phone),
      service_requested: service,
      budget,
      location: normalizeText(customer.location),
      enquiry_date:
        customer.enquiry_date || new Date().toISOString(),
      status: customer.status || "New Enquiry",
      notes: customer.notes || "",
      customer_key: `${business}|${email}`
    }
  };
});

const incoming = $("Prepare Universal CRM Records")
  .all()
  .map(item => item.json);

const sheetRows = $("Check Existing Customers")
  .all()
  .map(item => item.json);

const normalize = value =>
  String(value ?? "").trim().toLowerCase();

const emailPattern =
  /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

// SAFETY: This Day 10 test expects exactly five
// existing records. Do not use this fixed count
// as a permanent production rule.
const EXPECTED_EXISTING_ROWS = 5;

if (sheetRows.length !== EXPECTED_EXISTING_ROWS) {
  throw new Error(
    `CRM safety stop: expected ${EXPECTED_EXISTING_ROWS} ` +
    `existing rows, received ${sheetRows.length}. ` +
    "Verify Google Sheets before proceeding."
  );
}

// Validate existing customer records.
const existingKeys = new Set();

for (const [index, row] of sheetRows.entries()) {
  if (
    !row ||
    typeof row !== "object" ||
    row.error
  ) {
    throw new Error(
      `Invalid Google Sheets row ${index + 1}`
    );
  }

  const business = normalize(row.business_name);
  const email = normalize(row.email);
  const storedKey = normalize(row.customer_key);

  if (
    !business ||
    !emailPattern.test(email) ||
    !storedKey
  ) {
    throw new Error(
      `Incomplete existing record at index ${index + 1}`
    );
  }

  const expectedKey = `${business}|${email}`;

  if (storedKey !== expectedKey) {
    throw new Error(
      `Customer key mismatch at existing record ${index + 1}`
    );
  }

  if (existingKeys.has(storedKey)) {
    throw new Error(
      `Duplicate key already exists in Google Sheets: ${storedKey}`
    );
  }

  existingKeys.add(storedKey);
}

// Validate and filter incoming customers.
const seenInBatch = new Set();
const newCustomers = [];

for (const [index, customer] of incoming.entries()) {
  const business = normalize(customer.business_name);
  const email = normalize(customer.email);
  const name = String(
    customer.customer_name ?? ""
  ).trim();

  const service = String(
    customer.service_requested ?? ""
  ).trim();

  if (
    !business ||
    !name ||
    !service ||
    !emailPattern.test(email)
  ) {
    throw new Error(
      `Invalid incoming customer at index ${index + 1}`
    );
  }

  const key = `${business}|${email}`;

  if (
    customer.customer_key &&
    normalize(customer.customer_key) !== key
  ) {
    throw new Error(
      `Incoming customer key mismatch at index ${index + 1}`
    );
  }

  // Already saved in Google Sheets.
  if (existingKeys.has(key)) {
    continue;
  }

  // Repeated within this incoming batch.
  if (seenInBatch.has(key)) {
    continue;
  }

  seenInBatch.add(key);

  newCustomers.push({
    json: {
      ...customer,
      business_name: business,
      customer_name: name,
      email,
      customer_key: key
    }
  });
}

return newCustomers;

const businessServices = {
  "solar energy": [
    "solar installation",
    "inverter repair",
    "battery replacement",
    "panel cleaning"
  ],

  "real estate": [
    "property inspection",
    "property purchase",
    "property rental"
  ],

  "e-commerce": [
    "online purchase",
    "product enquiry",
    "order tracking",
    "laptop purchase"
  ],

  "digital agency": [
    "social media advertising",
    "content creation",
    "seo services",
    "website design"
  ],

  "electronics": [
    "laptop purchase",
    "phone purchase",
    "device repair"
  ],

  "digital marketing": [
    "social media advertising",
    "content creation",
    "seo services"
  ]
};

const normalize = value =>
  String(value ?? "").trim().toLowerCase();

return $input.all().map(item => {
  const customer = item.json;

  const business = normalize(
    customer.business_name ?? customer.business_type
  );

  const service = normalize(
    customer.service_requested
  );

  const supportedBusiness =
    Object.prototype.hasOwnProperty.call(
      businessServices,
      business
    );

  const supportedService =
    supportedBusiness &&
    businessServices[business].includes(service);

  let routingStatus = "manual_review";
  let routingReason = "unsupported_business";

  if (supportedBusiness && supportedService) {
    routingStatus = "ready";
    routingReason = "supported_service";
  } else if (supportedBusiness) {
    routingReason = "unsupported_service";
  }

  return {
    json: {
      ...customer,
      business_normalized: business,
      service_normalized: service,
      routing_status: routingStatus,
      routing_reason: routingReason
    }
  };
});

const records = $input.all();

const urgencyWords = [
  "urgent", "emergency", "immediately",
  "asap", "critical", "today"
];

const businessRules = {
  "solar energy": {
    mediumBudget: 100000,
    highBudget: 400000,
    services: {
      "solar installation": {
        points: 20,
        team: "Solar Installation Team"
      },
      "inverter repair": {
        points: 20,
        team: "Technical Repair Team"
      },
      "battery replacement": {
        points: 15,
        team: "Battery Service Team"
      },
      "panel cleaning": {
        points: 10,
        team: "Solar Maintenance Team"
      }
    }
  },
  "real estate": {
    mediumBudget: 100000,
    highBudget: 500000,
    services: {
      "property inspection": {
        points: 15,
        team: "Property Inspection Team"
      },
      "property purchase": {
        points: 20,
        team: "Property Sales Team"
      },
      "property rental": {
        points: 15,
        team: "Property Rental Team"
      }
    }
  }
};

return records.map(item => {
  const customer = { ...item.json };

  const business = String(
    customer.business_name ?? ""
  ).trim().toLowerCase();

  const service = String(
    customer.service_requested ?? ""
  ).trim().toLowerCase();

  const notes = String(
    customer.notes ?? ""
  ).toLowerCase();

  const urgencyText = String(
    customer.urgency ?? ""
  ).toLowerCase();

  const combinedText = `${urgencyText} ${notes}`;

  const rule = businessRules[business];
  const serviceRule = rule?.services[service];

  // Unsupported records must not receive
  // normal priority or department assignment.
  if (!rule || !serviceRule) {
    return {
      json: {
        ...customer,
        priority_score: null,
        priority_level: "Unassigned",
        assigned_team: "Manual Review",
        priority_status: "Needs Review",
        priority_reason: "Unsupported business or service"
      }
    };
  }

  // Urgency: maximum 40 points.
  const isUrgent = urgencyWords.some(word =>
    new RegExp(
      `\\b${word}\\b`, "i"
    ).test(combinedText)
  );

  const urgencyScore = isUrgent ? 40 : 0;

  // Budget: maximum 30 points.
  const rawBudget = customer.budget;
  const budgetText = String(rawBudget ?? "").trim();

  const validBudget =
    budgetText !== "" &&
    /^\d+(\.\d+)?$/.test(budgetText) &&
    Number.isFinite(Number(budgetText)) &&
    Number(budgetText) >= 0;

  const budget = validBudget
    ? Number(budgetText)
    : null;

  let budgetScore = 0;

  if (budget !== null) {
    if (budget >= rule.highBudget) {
      budgetScore = 30;
    } else if (budget >= rule.mediumBudget) {
      budgetScore = 20;
    } else if (budget > 0) {
      budgetScore = 10;
    }
  }

  // Service: maximum 20 points.
  const serviceScore = serviceRule.points;

  // Completeness: maximum 10 points.
  const nameValid = String(
    customer.customer_name ?? ""
  ).trim().length > 0;

  const email = String(
    customer.email ?? ""
  ).trim();

  const emailValid =
    /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

  const contactScore =
    (nameValid ? 5 : 0) +
    (emailValid ? 5 : 0);

  const totalScore =
    urgencyScore +
    budgetScore +
    serviceScore +
    contactScore;

  let priorityLevel = "Low";

  if (totalScore >= 70) {
    priorityLevel = "High";
  } else if (totalScore >= 40) {
    priorityLevel = "Medium";
  }

  return {
    json: {
      ...customer,
      priority_score: totalScore,
      priority_level: priorityLevel,
      assigned_team: serviceRule.team,
      priority_status: "Scored",
      priority_reason: [
        `Urgency: ${urgencyScore}/40`,
        `Budget: ${budgetScore}/30`,
        `Service: ${serviceScore}/20`,
        `Completeness: ${contactScore}/10`
      ].join("; ")
    }
  };
});

return [
  {
    json: {
      business_name: "solar energy",
      customer_name: "Test Customer A",
      email: "testa@example.com",
      service_requested: "Solar installation",
      budget: 500000,
      urgency: "Emergency",
      notes: "Customer needs urgent installation"
    }
  },
  {
    json: {
      business_name: "solar energy",
      customer_name: "Test Customer B",
      email: "testb@example.com",
      service_requested: "Inverter repair",
      budget: 50000,
      urgency: "Normal",
      notes: "Routine repair request"
    }
  },
  {
    json: {
