];

const customers = [
  {
    customer_name: "Ada Okoro",
    email: "ada@example.com",
    business_name: "solar energy",
    service_requested: "Solar installation",
    priority: "high",
    status: "New Enquiry"
  },
  {
    customer_name: "Grace Peter",
    email: "grace@example.com",
    business_name: "solar energy",
    service_requested: "Inverter repair",
    priority: "medium",
    status: "New Enquiry"
  },
  {
    customer_name: "Mary Jane",
    email: "mary@example.com",
    business_name: "real estate",
    service_requested: "Property inspection",
    priority: "low",
    status: "Completed"
  }
];

const now = new Date();

return customers.map(customer => {
  const status = customer.status
    .trim()
    .toLowerCase();

  const priority = customer.priority
    .trim()
    .toLowerCase();

  const needsFollowUp = [
    "new enquiry",
    "pending",
    "awaiting response"
  ].includes(status);

  const days = priority === "high"
    ? 1
    : priority === "medium"
    ? 2
    : 3;

  const followUpDate = new Date(now);
  followUpDate.setUTCDate(
    followUpDate.getUTCDate() + days
  );

  return {
    json: {
      ...customer,
      needs_follow_up: needsFollowUp,
      follow_up_status: needsFollowUp
        ? "Pending Follow-Up"
        : "No Follow-Up Required",
     follow_up_date: needsFollowUp
  ? followUpDate.toISOString().slice(0, 10)
  : null,
      follow_up_channel: "Manual",
      message_generated: false
    }
  };
});

const customers = $input.all();

return customers.map(item => {
  const customer = item.json;

  const name = String(
    customer.customer_name || "Customer"
  ).trim();

  const service = String(
    customer.service_requested || ""
  ).trim();

  const business = String(
    customer.business_name || ""
  ).toLowerCase();

  const priority = String(
    customer.priority || "low"
  ).toLowerCase();

  const needsFollowUp =
    customer.needs_follow_up === true;

  let message = null;
  let messageType = "none";

  if (needsFollowUp) {
    const firstName = name.split(/\s+/)[0];

    if (business.includes("solar")) {
      message =
        `Hello ${firstName}, thank you for your ` +
        `interest in our ${service} service. ` +
        `We are following up on your enquiry. ` +
        `Would you like to discuss the next steps?`;

      messageType = "solar_follow_up";

    } else if (business.includes("real estate")) {
      message =
        `Hello ${firstName}, we are following up ` +
        `on your enquiry about ${service}. ` +
        `Would you like us to assist you with ` +
        `the next steps or arrange a consultation?`;

      messageType = "real_estate_follow_up";

    } else {
      message =
        `Hello ${firstName}, we are following up ` +
        `on your enquiry regarding ${service}. ` +
        `Please let us know if you still need ` +
        `assistance.`;

      messageType = "general_follow_up";
    }
  }

  return {
    json: {
      ...customer,
      follow_up_message: message,
      message_type: messageType,
      message_generated: needsFollowUp,
      message_priority: priority,
      delivery_status: needsFollowUp
        ? "Draft - Not Sent"
        : "Not Required"
    }
  };
});

const customers = $input.all();

const today = new Date()
  .toISOString()
  .slice(0, 10);

return customers.map(item => {
  const customer = item.json;

  const needsFollowUp =
    customer.needs_follow_up === true;

  const messageReady =
    customer.message_generated === true &&
    typeof customer.follow_up_message === "string" &&
    customer.follow_up_message.trim() !== "";

  const dueDate = customer.follow_up_date;

  let scheduleStatus = "Not Required";
  let actionRequired = false;
  let daysUntilFollowUp = null;

  if (needsFollowUp) {
    if (!dueDate ||
        !/^\d{4}-\d{2}-\d{2}$/.test(dueDate) ||
        !Number.isFinite(Date.parse(dueDate)) ||
        new Date(dueDate).toISOString().slice(0, 10) !== dueDate) {
      scheduleStatus = "Missing or Invalid Date";
    } else {
      const todayMs = Date.parse(today);
      const dueMs = Date.parse(dueDate);

      daysUntilFollowUp = Math.round(
        (dueMs - todayMs) / 86400000
      );

      if (daysUntilFollowUp < 0) {
        scheduleStatus = "Overdue";
        actionRequired = true;
      } else if (daysUntilFollowUp === 0) {
        scheduleStatus = "Due Today";
        actionRequired = true;
      } else {
        scheduleStatus = "Scheduled";
      }
    }
  }

  return {
    json: {
      ...customer,
      schedule_status: scheduleStatus,
      days_until_follow_up: daysUntilFollowUp,
      action_required: actionRequired,
      message_ready_for_review:
        needsFollowUp && messageReady,
      follow_up_processing_status:
        !needsFollowUp
          ? "Not Required"
          : !messageReady
          ? "Message Missing"
          : scheduleStatus === "Missing or Invalid Date"
          ? "Schedule Error"
          : "Awaiting Manual Review",
      message_sent: false
    }
  };
});

const items = $input.all();

const summary = {
  total_customers: items.length,
  messages_generated: 0,
  scheduled: 0,
  overdue: 0,
  due_today: 0,
  not_required: 0,
  fallback: 0,
  sent_messages: 0,
  errors: []
};

const validStatuses = [
  "Scheduled",
  "Overdue",
  "Due Today",
  "Not Required"
];

for (const item of items) {
  const c = item.json;

  if (c.message_generated === true) {
    summary.messages_generated++;
  }

  if (c.message_sent === true) {
    summary.sent_messages++;
  }

  switch (c.schedule_status) {
    case "Scheduled":
      summary.scheduled++;
      break;
    case "Overdue":
      summary.overdue++;
      break;
    case "Due Today":
      summary.due_today++;
      break;
    case "Not Required":
      summary.not_required++;
      break;
    default:
      summary.fallback++;
  }

  if (!validStatuses.includes(c.schedule_status)) {
    summary.errors.push(
      `${c.customer_name}: Invalid schedule status`
    );
  }

  if (
    c.needs_follow_up === true &&
    c.message_generated !== true
  ) {
    summary.errors.push(
      `${c.customer_name}: Missing follow-up message`
    );
  }

  if (c.message_sent === true) {
    summary.errors.push(
      `${c.customer_name}: Unexpected sent message`
    );
  }
}

summary.validation_passed =
  summary.errors.length === 0 &&
  summary.sent_messages === 0 &&
  summary.total_customers ===
    summary.scheduled +
    summary.overdue +
    summary.due_today +
    summary.not_required +
    summary.fallback;

return [{ json: summary }];

const items = $input.all();
const now = new Date();

return items.map(item => {
  const c = item.json;

  const status = String(
    c.status || "New Enquiry"
  ).trim().toLowerCase();

  const rawPriority = String(
    c.priority || c.priority_level || ""
  ).trim().toLowerCase();

  const priority = [
    "high", "medium", "low"
  ].includes(rawPriority)
    ? rawPriority
    : "unassigned";

  const needsFollowUp = [
    "new enquiry",
    "pending",
    "awaiting response"
  ].includes(status);

  const days = priority === "high"
    ? 1
    : priority === "medium"
    ? 2
    : priority === "low"
    ? 3
    : null;

  const dueDate = new Date(now);

  if (days !== null) {
    dueDate.setUTCDate(
      dueDate.getUTCDate() + days
    );
  }

  return {
    json: {
      ...c,
      priority,
      needs_follow_up: needsFollowUp,
      follow_up_status: needsFollowUp
        ? "Pending Follow-Up"
        : "No Follow-Up Required",
      follow_up_date:
        needsFollowUp && days !== null
          ? dueDate.toISOString().slice(0, 10)
          : null,
      follow_up_channel: "Manual",
      message_generated: false
    }
  };
});

const items = $input.all();
const now = new Date().toISOString();

return items.map((item) => {
  const customer = item.json;

  const customerKey = String(
    customer.customer_key ||
    `${customer.business_name || "unknown"}|${customer.email || ""}`
  ).trim().toLowerCase();

  const needsFollowUp =
    customer.needs_follow_up === true;

  const trackingStatus = needsFollowUp
    ? "Pending"
    : "Not Required";

  return {
    json: {
      ...customer,
      customer_key: customerKey,
      tracking_status: trackingStatus,
      follow_up_attempts: 0,
      last_follow_up_at: null,
      customer_response: null,
      tracking_created_at: now,
      tracking_updated_at: now
    }
  };
});

const items = $input.all();

return items.map(item => {
  const customer = item.json;

  // Only record an attempt when explicitly confirmed.
  const attemptConfirmed =
    customer.attempt_confirmed === true;

  const eligible =
    customer.needs_follow_up === true &&
    customer.tracking_status === "Pending";

  const shouldRecord =
    attemptConfirmed && eligible;

  const previousAttempts = Number(
    customer.follow_up_attempts ?? 0
  );

  const now = new Date().toISOString();

  return {
    json: {
      ...customer,

      follow_up_attempts:
        previousAttempts + (shouldRecord ? 1 : 0),

      last_follow_up_at: shouldRecord
        ? now
        : customer.last_follow_up_at ?? null,

      tracking_status: shouldRecord
        ? "Contacted"
        : customer.tracking_status,

      tracking_updated_at: shouldRecord
        ? now
        : customer.tracking_updated_at,

      attempt_recorded: shouldRecord
    }
  };
});

const items = $input.all();
const seen = new Set();

return items.map(item => {
  const customer = item.json;

  const customerKey = String(
    customer.customer_key || ""
  ).trim().toLowerCase();

  const attemptId = String(
    customer.attempt_id || ""
  ).trim();

  const confirmed =
    customer.attempt_recorded === true;

  // A valid attempt must have an ID.
  const validAttempt =
    confirmed &&
    customerKey !== "" &&
    attemptId !== "";

  const duplicate =
    validAttempt && seen.has(attemptId);

  if (validAttempt && !duplicate) {
    seen.add(attemptId);
  }

  return {
    json: {
      ...customer,
      duplicate_attempt: duplicate,
      attempt_validation_passed:
        !confirmed || (validAttempt && !duplicate),
      safe_to_update_crm:
        validAttempt && !duplicate
    }
  };
});

const items = $input.all();

const allowedStatuses = [
  "Pending",
  "Contacted",
  "Responded",
  "Closed",
  "Not Required"
];

return items.map(item => {
  const customer = item.json;

  const currentStatus =
    customer.tracking_status || "Pending";

  const response = String(
    customer.customer_response || ""
  ).trim();

  const closeConfirmed =
    customer.close_confirmed === true;

  let nextStatus = currentStatus;

  // Only confirmed contact or response events
  // should change the tracking status.
  if (currentStatus !== "Closed" &&
      currentStatus !== "Not Required") {

    if (closeConfirmed) {
      nextStatus = "Closed";
    } else if (response.length > 0) {
      nextStatus = "Responded";
    }
  }

  const validStatus =
    allowedStatuses.includes(nextStatus);

  const statusChanged =
    nextStatus !== currentStatus;

  return {
    json: {
      ...customer,
      tracking_status: nextStatus,
      response_received: response.length > 0,
      status_changed: statusChanged,
      status_validation_passed: validStatus,
      tracking_updated_at: statusChanged
        ? new Date().toISOString()
        : customer.tracking_updated_at
    }
  };
});

const items = $input.all();

return items.map(item => {
  const customer = item.json;

  const customerKey = String(
    customer.customer_key || ""
  ).trim().toLowerCase();

  const validStatus =
    customer.status_validation_passed === true;

  const statusChanged =
    customer.status_changed === true;

  const validKey = customerKey.length > 0;

  // No write operations are authorised yet.
  const safeToWrite = false;

  const updatePreview = {
    customer_key: customerKey,
    tracking_status: customer.tracking_status,
    follow_up_attempts:
      customer.follow_up_attempts ?? 0,
    last_follow_up_at:
      customer.last_follow_up_at ?? null,
    customer_response:
      customer.customer_response ?? null
  };

  return {
    json: {
      ...customer,
      crm_update_preview: updatePreview,
      crm_update_required:
        validKey && validStatus && statusChanged,
      crm_update_validated:
        validKey && validStatus,
      crm_write_authorized: safeToWrite
    }
  };
});

const items = $input.all();

const results = {
  total_customers: items.length,
  tracking_valid: 0,
  duplicate_attempts: 0,
  responses_received: 0,
  status_changes: 0,
  crm_updates_required: 0,
  crm_writes_authorized: 0,
  errors: []
};

const allowedStatuses = [
  "Pending",
  "Contacted",
  "Responded",
  "Closed",
  "Not Required"
];

for (const item of items) {
  const c = item.json;

  if (
    c.status_validation_passed === true &&
    allowedStatuses.includes(c.tracking_status) &&
    c.crm_update_validated === true
  ) {
