const events = $input.all().map(item => item.json);

const customers = new Map();
const seenEvents = new Set();
const history = [];

let duplicatesBlocked = 0;
let attemptsRecorded = 0;
let responsesRecorded = 0;
let closuresRecorded = 0;

for (const event of events) {
  const key = String(event.customer_key || "")
    .trim().toLowerCase();

  const eventId = String(event.attempt_id || "")
    .trim();

  // Reject events without valid identifiers.
  if (!key || !eventId) {
    history.push({
      event_id: eventId,
      accepted: false,
      reason: "Missing identifier"
    });
    continue;
  }

  const uniqueId = `${key}|${eventId}`;

  if (seenEvents.has(uniqueId)) {
    duplicatesBlocked++;

    history.push({
      event_id: eventId,
      accepted: false,
      reason: "Duplicate event"
    });
    continue;
  }

  // Validate event type and confirmation
  // before recording its ID.
  const validEvent =
    (event.event_type === "contact_attempt" &&
      event.attempt_confirmed === true) ||
    (event.event_type === "customer_response" &&
      typeof event.customer_response === "string" &&
      event.customer_response.trim() !== "") ||
    (event.event_type === "close_customer" &&
      event.close_confirmed === true);

  if (!validEvent) {
    history.push({
      event_id: eventId,
      accepted: false,
      reason: "Invalid or unconfirmed event"
    });
    continue;
  }

  if (!customers.has(key)) {
    customers.set(key, {
      customer_key: key,
      tracking_status: "Pending",
      follow_up_attempts: 0,
      customer_response: null,
      last_follow_up_at: null
    });
  }

  const customer = customers.get(key);
  const now = new Date().toISOString();

  if (customer.tracking_status === "Closed") {
    history.push({
      event_id: eventId,
      accepted: false,
      reason: "Customer already closed"
    });
    continue;
  }

  seenEvents.add(uniqueId);

  if (event.event_type === "contact_attempt") {
    customer.follow_up_attempts++;
    customer.last_follow_up_at = now;
    customer.tracking_status = "Contacted";
    attemptsRecorded++;
  }

  if (event.event_type === "customer_response") {
    customer.customer_response =
      event.customer_response.trim();
    customer.tracking_status = "Responded";
    responsesRecorded++;
  }

  if (event.event_type === "close_customer") {
    customer.tracking_status = "Closed";
    closuresRecorded++;
  }

  history.push({
    event_id: eventId,
    accepted: true,
    event_type: event.event_type,
    status_after: customer.tracking_status
  });
}

const finalCustomers = [...customers.values()];

return [{
  json: {
    total_events: events.length,
    unique_customers: finalCustomers.length,
    attempts_recorded: attemptsRecorded,
    duplicates_blocked: duplicatesBlocked,
    responses_recorded: responsesRecorded,
    closures_recorded: closuresRecorded,
    customers: finalCustomers,
    event_history: history,
    crm_write_authorized: false
  }
}];

