const events = $input.all().map(item => item.json);

const MAX_RETRIES = 2;

return events.map(event => {
  const result = { ...event };

  result.retry_attempts = 0;
  result.recovery_status = "not_required";
  result.recovery_log = [];
  result.crm_updated = false;

  // Block unsafe configurations
  if (
    result.simulation_mode !== true ||
    result.write_authorized !== false
  ) {
    result.recovery_status = "blocked";
    result.recovery_log.push("Unsafe configuration");
    return { json: result };
  }

  // Do not retry successful or duplicate events
  if (result.simulation_result !== "failed") {
    result.recovery_log.push("No retry required");
    return { json: result };
  }

  // Retry simulation
  for (let attempt = 1; attempt <= MAX_RETRIES; attempt++) {
    result.retry_attempts = attempt;

    result.recovery_log.push(
      `Retry attempt ${attempt}`
    );

    // Permanent failures never recover
    const retrySucceeded =
      event.permanent_failure !== true &&
      attempt === 1;

    if (retrySucceeded) {
      result.recovery_status = "recovered";
      result.simulation_result = "recovered";
      result.retry_required = false;
      result.simulated_new_status =
        result.proposed_status;

      result.recovery_log.push(
        "Recovery successful"
      );
      break;
    }
  }

  if (result.recovery_status !== "recovered") {
    result.recovery_status = "exhausted";
    result.retry_required = false;
