function processRun(events, runName) {
  let accepted = 0;
  let replayed = 0;

  const decisions = [];

  for (const eventId of events) {
    if (history.has(eventId)) {
      replayed++;

      decisions.push({
        event_id: eventId,
        decision: "replay_blocked"
      });
    } else {
      accepted++;

      history.add(eventId);

      decisions.push({
        event_id: eventId,
        decision: "accepted"
      });
    }
  }

  return {
    run: runName,
    accepted,
    replayed,
    decisions
  };
}

