const allowedTransitions = {
  open: ["acknowledged", "escalated", "resolved"],
  acknowledged: ["escalated", "resolved"],
  escalated: ["acknowledged", "resolved"],
  resolved: []
};

const results = tests.map(event => {
  const duplicate = history.some(
    row => row.event_id === event.event_id
  );

  const alertRecords = history.filter(
    row => row.alert_id === event.alert_id
  );

  const current = alertRecords.length
    ? alertRecords[alertRecords.length - 1].alert_state
    : null;

  let decision = "REJECT_INVALID_TRANSITION";
  let reason = "";

  if (duplicate) {
    decision = "REJECT_DUPLICATE";
    reason = "Event ID already processed";
  } else if (!current) {
    decision = "REJECT_UNKNOWN_ALERT";
    reason = "Alert not found in history";
  } else if (current === "resolved") {
    decision = "REJECT_RESOLVED_ALERT";
    reason = "Resolved alerts cannot transition";
  } else if (
    !allowedTransitions[current]?.includes(event.target_state)
  ) {
    reason = "Transition not permitted";
  } else if (
    event.event_type !== event.target_state
  ) {
    reason = "Event type and target state mismatch";
  } else {
    decision = "ACCEPT";
    reason = "Valid new event and transition";
  }

  return {
    event_id: event.event_id,
    alert_id: event.alert_id,
    current_state: current,
    target_state: event.target_state,
    duplicate,
    decision,
    reason
  };
});

