const seenEvents = new Set();
const seenAlerts = new Set();

for (const row of rows) {
  const eventId = String(row.event_id ?? '').trim();
  const alertId = String(row.alert_id ?? '').trim();
  const state = clean(row.alert_state);
  const severity = clean(
    row.severity ?? row.alert_severity
  );

  const problems = [];

  if (!eventId) problems.push('Missing event ID');
  if (!alertId) problems.push('Missing alert ID');

  if (eventId && seenEvents.has(eventId)) {
    problems.push('Duplicate event ID');
  }

  if (alertId && seenAlerts.has(alertId)) {
    problems.push('Duplicate alert ID');
  }

  if (!allowedStates.includes(state)) {
    problems.push('Invalid alert state');
  }

  if (clean(row.processing_status) !== 'accepted') {
    problems.push('Event not accepted');
  }

  if (problems.length > 0) {
    metrics.invalid_records++;

    invalidDetails.push({
      event_id: eventId,
      alert_id: alertId,
      problems
    });

    continue;
  }

  seenEvents.add(eventId);
  seenAlerts.add(alertId);

  if (state === 'open') metrics.open_alerts++;

  if (state === 'acknowledged') {
    metrics.acknowledged_alerts++;
  }

  if (state === 'resolved') {
    metrics.resolved_alerts++;
  }

  if (state !== 'resolved') {
    metrics.unresolved_alerts++;
  }

  if (allowedSeverities.includes(severity)) {
    if (severity === 'critical') {
      metrics.critical_alerts++;
    }

    if (severity === 'warning') {
      metrics.warning_alerts++;
    }

    if (severity === 'info') {
      metrics.info_alerts++;
    }

    if (
      severity === 'critical' &&
      state !== 'resolved'
    ) {
      metrics.critical_unresolved++;
    }
  } else {
    metrics.unknown_severity++;
  }
}

