const allowedStates = [
  "open",
  "acknowledged",
  "resolved"
];

const allowedSeverities = [
  "critical",
  "warning",
  "info"
];

const seen = new Set();

let valid = 0;
let invalidStates = 0;
let missingSeverity = 0;
let duplicateIds = 0;

for (const alert of alerts) {
  if (allowedStates.includes(alert.status)) {
    valid++;
  } else {
    invalidStates++;
  }

  if (!allowedSeverities.includes(alert.severity)) {
    missingSeverity++;
  }

  if (seen.has(alert.alert_id)) {
    duplicateIds++;
  } else {
    seen.add(alert.alert_id);
  }
}

const validationPassed =
  alerts.length === 6 &&
  valid === 5 &&
  invalidStates === 1 &&
  missingSeverity === 1 &&
  duplicateIds === 1;

