const records = $input.all().map(item => item.json);

const requiredFields = [
  "event_id",
  "alert_id",
  "status",
  "severity"
];

const validStates = [
  "open",
  "acknowledged",
  "resolved"
];

const validSeverities = [
  "critical",
  "warning",
  "info"
];

const errors = [];
const validRecords = [];
const invalidRecords = [];

for (let i = 0; i < records.length; i++) {
  const record = records[i];
  const recordErrors = [];

  if (
    !record ||
    typeof record !== "object" ||
    Array.isArray(record)
  ) {
    recordErrors.push("Invalid record structure");
  } else {
    for (const field of requiredFields) {
      if (
        typeof record[field] !== "string" ||
        record[field].trim() === ""
      ) {
        recordErrors.push(
          `Missing or invalid field: ${field}`
        );
      }
    }

    if (
      typeof record.status === "string" &&
      record.status.trim() !== "" &&
      !validStates.includes(record.status)
    ) {
      recordErrors.push("Unsupported alert state");
    }

    if (
      typeof record.severity === "string" &&
      record.severity.trim() !== "" &&
      !validSeverities.includes(record.severity)
    ) {
      recordErrors.push("Unsupported severity");
    }
  }

  if (recordErrors.length === 0) {
    validRecords.push(record);
  } else {
    invalidRecords.push({
      record_number: i + 1,
      event_id: record?.event_id ?? null,
      errors: recordErrors
    });

    errors.push(...recordErrors);
  }
}

const result = {
  diagnostic: "Day 25 Step 25.2",
  total_records: records.length,
  valid_records: validRecords.length,
  invalid_records: invalidRecords.length,
  total_errors: errors.length,
  invalid_details: invalidRecords,
  data_quality_passed: invalidRecords.length === 0,
  validation_test_passed:
    records.length === 6 &&
    validRecords.length === 4 &&
    invalidRecords.length === 2 &&
    errors.length === 2,
  crm_writes: 0,
  notifications_sent: 0
};

return [{ json: result }];

const records = $input.all().map(item => item.json);

const seen = new Map();
const uniqueRecords = [];
const duplicates = [];
const invalidIds = [];

for (let i = 0; i < records.length; i++) {
  const record = records[i];

  const id = record.alert_id;

  if (
    typeof id !== "string" ||
    id.trim() === ""
  ) {
    invalidIds.push({
      record_number: i + 1,
      reason: "Missing or invalid alert ID"
    });
    continue;
  }

  const normalizedId = id.trim();

  if (seen.has(normalizedId)) {
    duplicates.push({
      alert_id: normalizedId,
      first_record: seen.get(normalizedId),
      duplicate_record: i + 1,
      event_id: record.event_id
    });
  } else {
    seen.set(normalizedId, i + 1);
    uniqueRecords.push(record);
  }
}

const testPassed =
  records.length === 6 &&
  uniqueRecords.length === 5 &&
  duplicates.length === 1 &&
  invalidIds.length === 0 &&
  duplicates[0]?.alert_id === "D25-A001";

return [{
  json: {
    diagnostic: "Day 25 Step 25.3",
    total_records: records.length,
    unique_alerts: uniqueRecords.length,
    duplicate_alerts: duplicates.length,
    invalid_alert_ids: invalidIds.length,
    duplicate_details: duplicates,
    invalid_id_details: invalidIds,
    unique_records: uniqueRecords,
    duplicate_detection_passed: testPassed,
    crm_writes: 0,
    notifications_sent: 0
  }
}];

const validStates = [
  "open",
  "acknowledged",
  "resolved"
];

const validSeverities = [
  "critical",
  "warning",
  "info"
];

const testCases = [
  {
    name: "Empty dataset",
    records: [],
    expected_status: "EMPTY_INPUT"
  },
  {
    name: "Invalid alert state",
    records: [{
      alert_id: "D25-T001",
      status: "pending",
      severity: "warning"
    }],
    expected_status: "INVALID_DATA"
  },
  {
    name: "Missing alert ID",
    records: [{
      status: "open",
      severity: "critical"
    }],
    expected_status: "INVALID_DATA"
  },
  {
    name: "Invalid severity",
    records: [{
      alert_id: "D25-T003",
      status: "open",
      severity: "extreme"
    }],
    expected_status: "INVALID_DATA"
  },
  {
    name: "Valid dataset",
    records: [{
      alert_id: "D25-T004",
      status: "resolved",
      severity: "info"
    }],
    expected_status: "VALID"
  }
];

function validate(records) {
  if (!Array.isArray(records)) {
    return "INVALID_DATA";
  }

  if (records.length === 0) {
    return "EMPTY_INPUT";
  }

  for (const record of records) {
    if (
      !record ||
      typeof record !== "object" ||
      Array.isArray(record)
    ) {
      return "INVALID_DATA";
    }

    if (
      typeof record.alert_id !== "string" ||
      record.alert_id.trim() === "" ||
      !validStates.includes(record.status) ||
      !validSeverities.includes(record.severity)
    ) {
      return "INVALID_DATA";
    }
  }

  return "VALID";
}

const results = testCases.map(test => {
  const actual = validate(test.records);

  return {
    test_name: test.name,
    expected_status: test.expected_status,
    actual_status: actual,
    passed: actual === test.expected_status
  };
});

const passed = results.filter(r => r.passed).length;
const failed = results.length - passed;

return [{
  json: {
    diagnostic: "Day 25 Step 25.4",
    total_tests: results.length,
    passed_tests: passed,
    failed_tests: failed,
    test_results: results,
    validation_passed: failed === 0,
